const cfg      = $('⚙️ Config G54').item.json;
const empRaw   = $('🏢 Obtener Empresa G54').item.json;
const prodRaw  = $('📦 Obtener Productos G54').item.json;
const kwRaw    = $('🔍 Obtener Keywords G54').item.json;

const emp   = empRaw.data  || empRaw  || {};
const prods = prodRaw.data || prodRaw || [];
const allKw = (kwRaw.data  || kwRaw   || []).filter(k => k.estado === 'activa');

// Brief real que el panel manda desde el 6-ago cuando el cliente lo completa en el modal
// antes de disparar el agente (POST /api/rrss/run-strategist) — horizonte_meses,
// periodo (fechas ya resueltas por el backend) y direccion_deseada. Máxima prioridad:
// es la elección explícita del cliente para ESTA corrida puntual, por encima de lo
// guardado en la estrategia anterior o de cualquier fallback fijo.
let webhookBody = {};
try { webhookBody = $('🔔 Webhook G54').item.json.body || {}; } catch(e) {}

// Parámetros del plan — leer desde G54 config del cliente (con fallback a Config G54)
let tiempo_horizonte   = cfg.G54_PLAN_HORIZONTE      || '3 meses';
let frecuencia_semanal = Number(cfg.G54_FRECUENCIA_SEMANAL) || 3;
// direccion_deseada: campo libre donde el cliente escribe hacia dónde quiere que vaya su estrategia.
// Se lee de /api/n8n/companies/{id}/rrss/estrategia (confirmado que ya expone este campo, 22-jul)
// como segunda prioridad, si el brief del webhook no la trae.
let direccion_deseada = '';
try {
  const rrssConfig = $('⚙️ Config RRSS Cliente G54').item.json;
  if (rrssConfig && rrssConfig.data) {
    if (rrssConfig.data.horizonte)          tiempo_horizonte   = rrssConfig.data.horizonte;
    if (rrssConfig.data.frecuencia_semanal) frecuencia_semanal = parseInt(rrssConfig.data.frecuencia_semanal);
    if (rrssConfig.data.direccion_deseada)  direccion_deseada  = String(rrssConfig.data.direccion_deseada).trim();
  }
} catch(e) { /* continueOnFail — usar fallback de Config G54 */ }

// Opciones de horizonte que el cliente puede elegir: 1, 3, 6 u 8 meses.
const mesesMap = { '1 mes':4, '3 meses':13, '6 meses':26, '8 meses':35 };
const horizonteMesesAWord = { 1:'1 mes', 3:'3 meses', 6:'6 meses', 8:'8 meses' };

// El brief del webhook pisa todo lo anterior, si vino con datos válidos.
if (webhookBody.horizonte_meses && horizonteMesesAWord[webhookBody.horizonte_meses]) {
  tiempo_horizonte = horizonteMesesAWord[webhookBody.horizonte_meses];
}
if (webhookBody.direccion_deseada) {
  direccion_deseada = String(webhookBody.direccion_deseada).trim();
}

const semanas  = mesesMap[tiempo_horizonte] || 13;
const total_ideas = semanas * frecuencia_semanal;

// Fecha de inicio/fin del plan — si el backend ya mandó `periodo` con las fechas resueltas
// (mismo brief de arriba), se usan tal cual en vez de recalcularlas acá; si no vino,
// se calculan como siempre a partir de hoy + el horizonte elegido.
let fecha_inicio_str, fecha_fin_str;
if (webhookBody.periodo && webhookBody.periodo.fecha_inicio && webhookBody.periodo.fecha_fin) {
  fecha_inicio_str = webhookBody.periodo.fecha_inicio;
  fecha_fin_str = webhookBody.periodo.fecha_fin;
} else {
  const fecha_inicio = new Date();
  const fecha_fin = new Date(fecha_inicio.getTime() + semanas * 7 * 86400000);
  fecha_inicio_str = fecha_inicio.toISOString().slice(0,10);
  fecha_fin_str = fecha_fin.toISOString().slice(0,10);
}

// Datos empresa
const empresa_nombre = emp.name              || '';
const industria      = emp.industry          || '';
const descripcion    = emp.description       || '';
const valor          = emp.value_proposition || '';
const ciudad         = emp.base_city         || '';
const web            = emp.website           || '';
const objetivo       = emp.primary_goal      || '';
const audiencia      = emp.target_market     || '';
const geografia      = emp.geography         || '';
const email          = (emp.emails||[])[0]   || '';

// Catálogo
const catalogo = prods.map(p => {
  const kw = (p.keywords||[]).join(', ');
  return `• ${p.name||''}: ${p.description||''}${kw?' ['+kw+']':''}`;
}).join('\n');

// Keywords por intención
const kwByIntencion = { local:[], comercial:[], informacional:[], transaccional:[] };
for (const k of allKw) {
  const intent = k.intencion || 'informacional';
  if (kwByIntencion[intent]) kwByIntencion[intent].push(k.keyword);
  else kwByIntencion.informacional.push(k.keyword);
}
const kwSection = `KEYWORDS EXISTENTES EN G54 (usar estas — NO inventar nuevas):
• Local/GEO:     ${kwByIntencion.local.join(' | ')         || 'N/A'}
• Comercial:     ${kwByIntencion.comercial.join(' | ')     || 'N/A'}
• Informacional: ${kwByIntencion.informacional.join(' | ') || 'N/A'}
• Transaccional: ${kwByIntencion.transaccional.join(' | ') || 'N/A'}`;

// Competidores (embebidos en el GET de empresa)
const competidores = (emp.competitors_known || []).filter(c => c.is_active);
const competidoresSection = competidores.length
  ? competidores.map(c => `• ${c.name}: ${c.url}`).join('\n')
  : 'No registrados — inferir principales competidores del nicho en la ciudad base.';
const competidoresNombres = competidores.length
  ? competidores.map(c => c.name).join(', ')
  : 'los competidores del nicho';

// Distribución TOFU/MOFU/BOFU
const dist_tofu = Math.round(total_ideas * 0.5);
const dist_mofu = Math.round(total_ideas * 0.3);
const dist_bofu = total_ideas - dist_tofu - dist_mofu;
const dist_txt  = `TOFU ${dist_tofu} posts (50%) · MOFU ${dist_mofu} posts (30%) · BOFU ${dist_bofu} posts (20%)`;

// Leer plataformas conectadas del cliente
let plataformas_conectadas = ['Instagram', 'Facebook']; // fallback default, solo si /api/social-channels falla del todo
try {
  const platRaw = $('🔗 Obtener Plataformas G54').item.json;
  if (platRaw && platRaw.data && Array.isArray(platRaw.data) && platRaw.data.length > 0) {
    const activos = platRaw.data.filter(p => p.is_active && p.has_credentials).map(p => p.platform).filter(Boolean);
    if (activos.length > 0) plataformas_conectadas = activos;
  }
} catch(e) {
  // continueOnFail — usar fallback
}
const plataformas_str = plataformas_conectadas.join(', ');

// Leer métricas de rendimiento anteriores desde Analytics AI
let metricas_resumen = '';
try {
  const metricasRaw = $('📈 Obtener Métricas Anteriores G54').item.json;
  if (metricasRaw && metricasRaw.data && metricasRaw.data.length > 0) {
    const ultimas = metricasRaw.data.slice(0, 4);
    metricas_resumen = ultimas.map(m =>
      `- ${m.periodo} (${m.tipo}): ${m.metricas?.posts_publicados || 0} posts, ` +
      `${m.metricas?.leads_generados || 0} leads, ` +
      `mejor plataforma: ${m.metricas?.mejor_plataforma || 'N/A'}, ` +
      `mejor contenido: ${m.metricas?.mejor_tipo_contenido || 'N/A'}`
    ).join('\n');
  }
} catch(e) { /* sin métricas disponibles aún — continueOnFail */ }


const prompt = `Responde ÚNICAMENTE en español. Todo el JSON de respuesta debe estar en español.

Actúa como un estratega senior especializado en crecimiento orgánico basado en SEO, AEO y GEO.

Tu función es generar la estrategia de contenido base de la empresa para los próximos ${tiempo_horizonte}. Esta estrategia será usada por todos los agentes del sistema G54 (Content AI, Distribution AI, Analytics AI) como referencia para cada pieza de contenido que produzcan.

NEGOCIO: ${empresa_nombre}
INDUSTRIA: ${industria}
DESCRIPCIÓN: ${descripcion}
PROPUESTA DE VALOR: ${valor}
CIUDAD BASE: ${ciudad} | WEB: ${web}
COBERTURA: ${geografia}
OBJETIVO PRINCIPAL: ${objetivo}
MERCADO OBJETIVO: ${audiencia}
HORIZONTE DEL PLAN: ${tiempo_horizonte} (${semanas} semanas)
PUBLICACIONES POR SEMANA: ${frecuencia_semanal}
TOTAL POSTS DEL PLAN: ${total_ideas}

PRODUCTOS / SERVICIOS:
${catalogo}

${kwSection}

COMPETIDORES CONOCIDOS:
${competidoresSection}
${metricas_resumen ? `\nRENDIMIENTO HISTÓRICO (últimas semanas registradas por Analytics AI):\n${metricas_resumen}\n\nUsa estos datos para ajustar el tipo de contenido, plataformas y frecuencia en el nuevo plan. Prioriza el formato y la plataforma con mejor rendimiento.` : ''}
${direccion_deseada ? `\nDIRECCIÓN SOLICITADA POR EL CLIENTE (OBLIGATORIO respetarla, no es opcional):\n${direccion_deseada}\n\nEsta estrategia TIENE que reflejar explícitamente esta dirección — no es una sugerencia, es un requisito del cliente.` : ''}

Entrega ÚNICAMENTE un JSON válido con esta estructura exacta (sin markdown, sin texto extra):
{
  "objetivo": "objetivo principal de la estrategia de contenido",
  "audiencia": "descripción detallada del público objetivo",
  "tono": "tono de comunicación en máximo 8 palabras (ej: Profesional, directo y cercano)",
  "frecuencia": "Plataforma1 Nx/sem, Plataforma2 Nx/sem (máximo 100 caracteres — desglosa ${frecuencia_semanal} publicaciones semanales EXACTAMENTE entre estas plataformas: ${plataformas_str}. Ej: \"Facebook 3x/sem, Instagram 2x/sem\". Los días y la justificación van en resumen_estrategico, NO aquí)",
  "director_cta": "${web}/contacto",
  "embudo": "TOFU X% / MOFU Y% / BOFU Z% (máximo 100 caracteres, solo el resumen numérico, SIN explicación aquí)",
  "plataformas": "Plataforma1, Plataforma2, Plataforma3",
  "pilares": "Pilar1, Pilar2, Pilar3",
  "kpis": "KPI1, KPI2, KPI3, KPI4",
  "resumen_estrategico": "3-4 párrafos: posicionamiento frente a competidores, propuesta de valor diferenciadora, enfoque SEO/AEO/GEO, cómo el plan de ${tiempo_horizonte} construye autoridad progresiva, POR QUÉ se eligieron esos días de publicación según el comportamiento de audiencias B2B industriales, y qué tipo de contenido corresponde a cada etapa del embudo (TOFU/MOFU/BOFU) y por qué",
  "mapa_preguntas_aeo": ["¿pregunta1?","¿pregunta2?","¿pregunta3?","¿pregunta4?","¿pregunta5?","¿pregunta6?","¿pregunta7?","¿pregunta8?"],
  "faqs": [
    {"q":"¿FAQ1?","a":"respuesta breve y útil"},
    {"q":"¿FAQ2?","a":"respuesta breve y útil"},
    {"q":"¿FAQ3?","a":"respuesta breve y útil"},
    {"q":"¿FAQ4?","a":"respuesta breve y útil"},
    {"q":"¿FAQ5?","a":"respuesta breve y útil"}
  ],
  "clusters": ["nombre-cluster-1","nombre-cluster-2","nombre-cluster-3"]
}
NOTA: NO generes "keyword_strategy" ni "plan_publicacion" — esos dos se arman en código a partir de datos reales, no hace falta que los inventes.

INSTRUCCIONES CLAVE:
1. LÍMITE ESTRICTO: los campos \`tono\`, \`frecuencia\` y \`embudo\` tienen un límite real de 100 caracteres en la base de datos — deben ser etiquetas cortas, NUNCA párrafos ni explicaciones. Toda la justificación y el detalle van en \`resumen_estrategico\`, que sí tiene espacio.
2. Para keyword_strategy usa EXCLUSIVAMENTE las keywords de la sección KEYWORDS EXISTENTES EN G54. Clasifícalas sin inventar nuevas.
3. El campo \`frecuencia\` debe desglosar las ${frecuencia_semanal} publicaciones semanales EXACTAMENTE por plataforma, formato "Plataforma Nx/sem, Plataforma Nx/sem" (ej: "Facebook 3x/sem, Instagram 2x/sem") — este desglose lo va a leer directamente el Ideas AI para saber cuántas ideas generar por plataforma cada semana, tiene que ser exacto. Los días de publicación y su justificación van en resumen_estrategico, no en frecuencia.
4. El resumen_estrategico debe mencionar explícitamente cómo ${empresa_nombre} se diferencia de: ${competidoresNombres}, y debe incluir los días de publicación recomendados con su justificación basada en el comportamiento de audiencias B2B industriales.
5. Sé específico y accionable para ${empresa_nombre} en ${ciudad}.
6. Usa ÚNICAMENTE estas plataformas: ${plataformas_str}. No uses plataformas que no estén en esta lista.
7. Genera TODO el contenido en ESPAÑOL.
8. Esta estrategia NO incluye ideas de contenido individuales — esas las genera el Ideas AI por separado, semana a semana, siguiendo este plan.`;

return [{ json: {
  empresa_nombre, industria, descripcion, valor, ciudad, web,
  objetivo, audiencia, geografia, email, catalogo, prompt,
  company_id: cfg.G54_COMPANY_ID,
  keywords_count: allKw.length,
