const raw = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text
  || $input.item.json.choices?.[0]?.message?.content || "{}";

let est;
try { est = JSON.parse(raw); }
catch(e) {
  const m = raw.match(/\{[\s\S]*\}/);
  try { est = m ? JSON.parse(m[0]) : {}; } catch(e2) { est = {}; }
}

const ctx = $("🔧 Preparar Contexto").item.json;

// Helper: convierte string a array (separa por comas o pipes)
const toArray = (v) => {
  if (Array.isArray(v)) return v;
  if (!v) return [];
  return v.split(/[,|]/).map(s => s.trim()).filter(Boolean);
};

// Helper: trunca a max 100 chars tomando solo la primera oración/frase
const truncate = (v, max = 100) => {
  if (!v) return "";
  const str = String(v);
  if (str.length <= max) return str;
  // Corta en el último espacio antes del límite
  return str.substring(0, max).replace(/\s+\S*$/, "").trim();
};


// keyword_strategy — formato Walter: [{kw, volumen, intencion}]. Se arma con las
// keywords REALES de G54 (ctx.allKeywords), no con lo que devuelva la IA — evita que
// invente keywords que no existen. "volumen" es una estimación relativa por longitud
// de frase (mientras no haya un dato real de volumen de búsqueda en ningún lado del
// proyecto), documentado como estimación, no como dato real de Google.
const estimarVolumen = (kw) => {
  const palabras = String(kw || "").trim().split(/\s+/).filter(Boolean).length || 1;
  return Math.max(80, Math.round(2200 / Math.pow(palabras, 1.6)));
};
const keywordStrategy = (ctx.allKeywords || []).map(k => ({
  kw: k.keyword,
  volumen: estimarVolumen(k.keyword),
  intencion: k.intencion || "informacional"
}));

// faqs — formato Walter: [{q, a}]. Viene de la IA (criterio genuino, no hay forma
// determinística de armar buenas respuestas) — solo se sanea la forma.
const faqsOut = Array.isArray(est.faqs)
  ? est.faqs.filter(f => f && f.q).map(f => ({ q: String(f.q).trim(), a: String(f.a || "").trim() }))
  : [];

// plan_publicacion — formato Walter: [{semana, posts, pilar}], una fila por CADA semana
// del horizonte. Se arma en código repartiendo los pilares ya generados en round-robin
// — pedirle esto a la IA en un horizonte de hasta 52 semanas es pedir que enumere 52
// filas sin truncarse ni una vez, mismo tipo de riesgo ya visto con otros campos largos
// en este proyecto (ver ítems de "la IA no sigue el 100% de las instrucciones").
const pilaresParaPlan = toArray(est.pilares);
const totalSemanasPlan = Number(ctx.semanas) || 1;
const postsPorSemana = Number(ctx.frecuencia_semanal) || 3;
const planPublicacion = [];
for (let s = 1; s <= totalSemanasPlan; s++) {
  planPublicacion.push({
    semana: s,
    posts: postsPorSemana,
    pilar: pilaresParaPlan.length ? pilaresParaPlan[(s - 1) % pilaresParaPlan.length] : ""
  });
}

return [{ json: {
  company_id:          Number(ctx.company_id),
  objetivo:            est.objetivo             || ctx.objetivo  || "",
  audiencia:           est.audiencia            || ctx.audiencia || "",
  tono:                truncate(est.tono || "profesional y directo"),
  frecuencia:          truncate(est.frecuencia  || ""),
  cta_principal:        est.cta_principal         || ctx.web       || "",
  embudo:              truncate(est.embudo      || ""),
  plataformas:         toArray(est.plataformas),
  pilares:             toArray(est.pilares),
  kpis:                toArray(est.kpis),
  resumen_estrategico: est.resumen_estrategico  || "",
  keyword_strategy:    keywordStrategy,
  mapa_preguntas_aeo:  toArray(est.mapa_preguntas_aeo),
  faqs:                faqsOut,
  clusters:            toArray(est.clusters),
  plan_publicacion:    planPublicacion,
  empresa_nombre:      ctx.empresa_nombre,
  email:               ctx.email,
  tiempo_horizonte:    ctx.tiempo_horizonte,
  // Listos para el contador de tiempo del panel — G54 los descarta hoy si no tiene
  // las columnas (mismo caso que resumen_estrategico, ítem 120), pero quedan mandados
  // de una vez para que empiecen a guardarse solos apenas Walter agregue fecha_inicio/fecha_fin.
  fecha_inicio:        ctx.fecha_inicio,
  fecha_fin:           ctx.fecha_fin,
  semanas_totales:     ctx.semanas,
  direccion_deseada:   ctx.direccion_deseada || ""
} }];
